public class CineScreenEncapsulation { static class CineScreen{private final int seatsTotal;private int seatsAvailable;CineScreen(int n){if(n<1)throw new IllegalArgumentException("Seats must be positive");seatsTotal=seatsAvailable=n;}boolean bookSeat(){if(seatsAvailable==0)return false;seatsAvailable--;return true;}void cancelSeat(){if(seatsAvailable<seatsTotal)seatsAvailable++;}int getSeatsAvailable(){return seatsAvailable;}}public static void main(String[]a){CineScreen s=new CineScreen(2);s.bookSeat();System.out.println(s.getSeatsAvailable());} }
